import json
import math


def main():
    # term(n) = (n^2+1)! / (n!)^(n+2); integer iff (n!)^(n+2) divides (n^2+1)!
    integer_ns = []
    for n in range(1, 101):
        num = math.factorial(n * n + 1)
        den = math.factorial(n) ** (n + 2)
        if num % den == 0:
            integer_ns.append(n)

    count = len(integer_ns)
    option_map = {0: "A", 1: "B", 2: "C"}
    letter = option_map.get(count, "D")  # D: more than 2

    result = {
        "final_answer": letter,
        "evidence": {
            "range": "n=1..100",
            "integer_term_count": count,
            "integer_n_values": integer_ns,
            "method": "exact integer divisibility test of (n^2+1)! by (n!)^(n+2)",
        },
    }
    print(json.dumps(result))


if __name__ == "__main__":
    main()
